// The stone (10 Nov 2026): the colour of your lantern, picked in Settings. It tints every sheet of glass in the
// window and colours the bricks you have laid; the orange light inside the lantern, and every orange "now" or due
// brick, never changes. Values come from the Settings sample Edison approved (.scratch/flash-redesign/directions/v2/
// settings.html, tint strength 3), drawn by logo-r2/lantern8/settings-icons.py.
//   s0, s1  the stone's light and dark tone (the icon's gradient)
//   tn      the tone that tints the glass, when it is not s0 by day or s1 at night (Snow and Ink)
//   br      the laid brick's colour, when it is not s1 by day or s0 at night
//   bp      the brick carries more of the stone by day (Teal, Moss, Wisteria, Ink read faint as clear glass)
// Quiet text keeps 4.5:1 on every stone, measured as solid colour; glass over a busy wallpaper is not measured.
(function () {
  const STONES = {"teal": {"day": {"s0": "#93DCD3", "s1": "#2E9C96", "bp": 1}, "night": {"s0": "#62C2BA", "s1": "#21807B"}}, "azure": {"day": {"s0": "#9CCBFF", "s1": "#3F86EA"}, "night": {"s0": "#6FA8F2", "s1": "#2E6CC8"}}, "wisteria": {"day": {"s0": "#D9B6FF", "s1": "#9150E0", "bp": 1}, "night": {"s0": "#BC8CF7", "s1": "#6A34B8"}}, "sakura": {"day": {"s0": "#FFC4D6", "s1": "#E56F98"}, "night": {"s0": "#EE93B2", "s1": "#A8406A"}}, "maple": {"day": {"s0": "#FF9E9E", "s1": "#D2363E"}, "night": {"s0": "#E5686D", "s1": "#9C232D"}}, "moss": {"day": {"s0": "#B2E3A4", "s1": "#3E9A4E", "bp": 1}, "night": {"s0": "#86C97A", "s1": "#2E7A3C"}}, "ink": {"day": {"s0": "#6A717E", "s1": "#1A1D24", "tn": "#C9CDD3", "br": "#2A2F38", "bp": 1}, "night": {"s0": "#8E939B", "s1": "#3A3E45"}}, "snow": {"day": {"s0": "#FFFFFF", "s1": "#7D9BC4", "tn": "#DCEAF8", "br": "#4F74A6"}, "night": {"s0": "#F2F5F9", "s1": "#A3AFBE", "tn": "#66738A"}}};
  const ORDER = ["teal", "azure", "wisteria", "sakura", "maple", "moss", "ink", "snow"];
  const NAMES = {"teal": "Teal", "azure": "Azure", "wisteria": "Wisteria", "sakura": "Sakura", "maple": "Maple", "moss": "Moss", "ink": "Ink", "snow": "Snow"};
  const ICONS = {"teal-day": "data:image/svg+xml;base64,", "teal-night": "data:image/svg+xml;base64,", "azure-day": "data:image/svg+xml;base64,", "azure-night": "data:image/svg+xml;base64,", "wisteria-day": "data:image/svg+xml;base64,", "wisteria-night": "data:image/svg+xml;base64,", "sakura-day": "data:image/svg+xml;base64,", "sakura-night": "data:image/svg+xml;base64,", "maple-day": "data:image/svg+xml;base64,", "maple-night": "data:image/svg+xml;base64,", "moss-day": "data:image/svg+xml;base64,", "moss-night": "data:image/svg+xml;base64,", "ink-day": "data:image/svg+xml;base64,", "ink-night": "data:image/svg+xml;base64,", "snow-day": "data:image/svg+xml;base64,", "snow-night": "data:image/svg+xml;base64,"};
  const pick = (stone) => (STONES[stone] ? stone : "teal");
  function apply(stone, night) {
    const c = STONES[pick(stone)][night ? "night" : "day"], root = document.documentElement;
    root.dataset.stone = pick(stone);
    root.style.setProperty("--stone-tone", night ? `color-mix(in srgb, ${c.tn || c.s1} 75%, black)` : c.tn || c.s0);
    root.style.setProperty("--stone-brick", c.br || (night ? c.s0 : c.s1));
    root.style.setProperty("--bk1", !night && c.bp ? "48%" : night ? "40%" : "30%");
    root.style.setProperty("--stone-glow", night ? c.s0 : c.tn || c.s0);   // the Skills sun glow
    root.style.setProperty("--bk2", !night && c.bp ? "68%" : night ? "55%" : "48%");
  }
  // the glass tone a theme gives a stone, for a picture of the other theme (Settings' Appearance previews)
  const tone = (stone, night) => { const c = STONES[pick(stone)][night ? "night" : "day"]; return night ? `color-mix(in srgb, ${c.tn || c.s1} 75%, black)` : c.tn || c.s0; };
  const icon = (stone, night) => ICONS[`${pick(stone)}-${night ? "night" : "day"}`];
  // the Dock wants a bitmap: draw the icon on a canvas (a data: SVG never taints it) and hand over a PNG
  function png(stone, night, size = 512) {
    return new Promise((resolve) => {
      const img = new Image();
      img.onload = () => { const cv = document.createElement("canvas"); cv.width = cv.height = size; cv.getContext("2d").drawImage(img, 0, 0, size, size); resolve(cv.toDataURL("image/png")); };
      img.onerror = () => resolve(null);
      img.src = icon(stone, night);
    });
  }
  window.Stone = { ORDER, NAMES, apply, icon, png, pick, tone };
})();
